public final class UpdateExperienceHost {
 static final JSONArray checks=new JSONArray();static final AtomicInteger requests=new AtomicInteger();static volatile String mode="good";static volatile CountDownLatch held,release;static final List<String> queries=Collections.synchronizedList(new ArrayList<>());
 static void check(String name,boolean value)throws Exception{checks.put(new JSONObject().put("name",name).put("pass",value));if(!value)throw new AssertionError(name);}
 static String content(List<ReleaseNotes.Block> blocks){StringBuilder out=new StringBuilder();for(ReleaseNotes.Block b:blocks)out.append(b.text).append('\n');return out.toString();}
 static JSONObject entry(int n)throws Exception{return new JSONObject().put("id",n+1).put("tag_name","v2.0."+n+"-gecko").put("draft",false).put("prerelease",false).put("html_url",ReleaseHistoryPolicy.WEB+"/tag/v2.0."+n+"-gecko").put("published_at","2026-10-30T12:00:00Z").put("body","# 2.0."+n+"：更新\n## 本次更新\n- 内容 "+n+"\n## 技术详情\nAES-GCM 原有边界，真机未测。");}
 static void waitFor(java.util.function.BooleanSupplier condition)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(!condition.getAsBoolean()&&System.nanoTime()<end)Thread.sleep(10);if(!condition.getAsBoolean())throw new AssertionError("Async condition timed out");}
 static void parser()throws Exception{
  String required="本次更新优化后台服务、网络应用与分享流程。默认关闭后台回复检测；网络设置支持一键保存并应用；完善入口、出口及整条线路分享。下载列表新增文件大小，保存位置移入详情。更新页面增加历史版本记录，打开环境新增可跳过的五秒概览页，代理 IP 详情支持通过当前环境访问 ip123 查询。";
  ReleaseNotes explicit=ReleaseNotes.parse(required,"## 本次更新\nAES-GCM 原有说明。提交待完成。真机未测。 [证据](https://example.org/report)",true);
  check("Exact controlled user paragraph survives",content(explicit.user).trim().equals(required));check("Technical input cannot promote its own user heading",content(explicit.technical).contains("AES-GCM")&&content(explicit.technical).contains("提交待完成")&&content(explicit.technical).contains("真机未测"));
  ReleaseNotes legacy=ReleaseNotes.legacy(entry(45).getString("body"));check("Document version title allows explicit user section",content(legacy.user).contains("内容 45"));check("Technical caveat stays technical",!content(legacy.user).contains("AES-GCM")&&content(legacy.technical).contains("真机未测"));
  ReleaseNotes unknown=ReleaseNotes.legacy("## 不确定的工程说明\nAES-GCM 既有事实\n### 本次更新\n不能越过技术祖先");check("Unknown legacy engineering section stays explicit technical text",unknown.user.isEmpty()&&content(unknown.technical).contains("不能越过"));
  ReleaseNotes unsectioned=ReleaseNotes.legacy("# 2.0.45（98）\n- 提交与测试边界保持原文");check("Unsectioned legacy body never invents a user summary",unsectioned.user.isEmpty()&&content(unsectioned.technical).contains("边界保持原文"));
  ReleaseNotes typed=ReleaseNotes.parse("# 简洁标题\n- 一项\n1. 二项\n```\n# code\n```","",true);check("Recognized heading/list/code wrappers become semantic blocks",typed.user.get(0).kind==ReleaseNotes.HEADING&&typed.user.get(1).kind==ReleaseNotes.BULLET&&typed.user.get(2).kind==ReleaseNotes.ORDERED&&typed.user.get(3).kind==ReleaseNotes.CODE&&typed.user.get(3).text.equals("# code"));
  check("Ordered instruction number remains visible",typed.user.get(2).text.equals("1. 二项"));check("Fenced code indentation retains meaning",ReleaseNotes.parse("```\n    return 1\n```","",true).user.get(0).text.equals("    return 1"));
  check("Link preserves label and target without Markdown wrapper",ReleaseNotes.inline("[发布页](https://example.org/a)").equals("发布页（https://example.org/a）"));check("Escaped punctuation and literal hashes survive",ReleaseNotes.inline("\\# hash * unmatched a_b_c").equals("# hash * unmatched a_b_c"));check("No HTML or script evaluation",ReleaseNotes.inline("<b>x</b> [x](javascript:evil)").contains("javascript:evil"));
  check("Balanced parentheses within link destination survive",ReleaseNotes.inline("[说明](https://example.org/a_(b))").equals("说明（https://example.org/a_(b)）"));
  check("Oversized notes yield an explicit original-page fallback",content(ReleaseNotes.parse("x".repeat(12001),"",true).technical).contains("官方发布页"));
 }
 static void policy()throws Exception{
  check("Canonical first page trusted",ReleaseHistoryPolicy.trusted(ReleaseHistoryPolicy.url(1)));check("Canonical last bounded page trusted",ReleaseHistoryPolicy.trusted(ReleaseHistoryPolicy.url(100)));
  for(String url:new String[]{ReleaseHistoryPolicy.url(1).replace("https:","http:"),ReleaseHistoryPolicy.url(1).replace("api.github.com","api.github.com.evil.invalid"),ReleaseHistoryPolicy.url(1).replace("api.github.com","user@api.github.com"),ReleaseHistoryPolicy.url(1)+"#x",ReleaseHistoryPolicy.url(1)+"&x=1",ReleaseHistoryPolicy.url(1).replace("page=1","page=101"),ReleaseHistoryPolicy.url(1).replace("page=1","page=01"),ReleaseHistoryPolicy.url(1).replace("/releases?","/%72eleases?"),ReleaseHistoryPolicy.url(1).replace("api.github.com","api.github.com:443")})check("Reject untrusted or noncanonical history URL "+url,!ReleaseHistoryPolicy.trusted(url));
  for(JSONObject invalid:new JSONObject[]{entry(1).put("draft",true),entry(1).put("prerelease",true),entry(1).put("draft","false"),entry(1).put("tag_name","v2.0.1-gecko-candidate"),entry(1).put("tag_name","v02.0.1-gecko"),entry(1).put("tag_name","v9999999999.0.1-gecko"),entry(1).put("name","2.0.1 开发候选"),entry(1).put("html_url","https://example.org/release")})check("Reject candidate/draft/malformed release",ReleaseHistoryPolicy.entry(invalid)==null);
  List<ReleaseHistoryPolicy.Entry> sorted=ReleaseHistoryPolicy.merge(Arrays.asList(ReleaseHistoryPolicy.entry(entry(9)),ReleaseHistoryPolicy.entry(entry(10))),Arrays.asList(ReleaseHistoryPolicy.entry(entry(45)),ReleaseHistoryPolicy.entry(entry(9))));check("Numeric reverse version merge and tag dedupe",sorted.size()==3&&sorted.get(0).version.equals("2.0.45")&&sorted.get(1).version.equals("2.0.10"));
  check("Missing date remains unknown",ReleaseHistoryPolicy.entry(entry(4).put("published_at","bad")).published==0);check("JSON MIME accepts charset",ReleaseHistoryPolicy.jsonType("Application/JSON; charset=utf-8")&&!ReleaseHistoryPolicy.jsonType("text/html"));
  boolean rejected=false;try{ReleaseHistoryPolicy.read(new ByteArrayInputStream(new byte[21]),20,()->false);}catch(IOException expected){rejected=true;}check("Unknown-length stream is bounded",rejected);rejected=false;try{ReleaseHistoryPolicy.read(new ByteArrayInputStream(new byte[2]),20,()->true);}catch(IOException expected){rejected=true;}check("Cancelled stream does not publish data",rejected);
  JSONObject metadata=new JSONObject().put("schema",1).put("version","2.0.46").put("versionCode",99).put("bytes",100).put("sha256","a".repeat(64)).put("downloadUrl",AppUpdatePolicy.asset("2.0.46")).put("signerSha256",AppUpdatePolicy.SIGNER).put("package","local.pocketchat").put("abi","arm64-v8a").put("minSdk",26).put("notes","用户说明").put("notesRole","user").put("technicalDetails","真机未测");
  AppUpdateInfo info=new AppUpdateInfo(metadata);check("Additive metadata preserves candidate identity and explicit notes role",info.code==99&&info.userNotes&&info.technicalDetails.equals("真机未测"));rejected=false;try{new AppUpdateInfo(metadata.put("signerSha256","b".repeat(64)));}catch(IOException expected){rejected=true;}check("Descriptive fields cannot bypass original signer policy",rejected);
 }
 static void transport(int port)throws Exception{
  Context context=new Context(Files.createTempDirectory("history-route").toFile());AppUpdateRoute.Selection selection=AppUpdateRoute.select(context,3,null);AtomicInteger opens=new AtomicInteger();AppUpdateTransfer.ConnectionFactory direct=url->{opens.incrementAndGet();return (HttpURLConnection)new URL("http://127.0.0.1:"+port+"/history?"+url.substring(url.indexOf('?')+1)).openConnection();};
  for(AppUpdateRoute.Purpose purpose:AppUpdateRoute.Purpose.values()){String origin=purpose==AppUpdateRoute.Purpose.FEED?AppUpdatePolicy.FEED:purpose==AppUpdateRoute.Purpose.APK?AppUpdatePolicy.asset("2.0.46"):ReleaseHistoryPolicy.url(1);AppUpdateRoute.Factory factory=new AppUpdateRoute.Factory(context,selection,AppUpdateRoute.OFFICIAL,direct,origin,purpose);boolean rejected=false;try{factory.open(purpose==AppUpdateRoute.Purpose.HISTORY?AppUpdatePolicy.FEED:ReleaseHistoryPolicy.url(1));}catch(IOException expected){rejected=true;}finally{factory.finished();}check("Exact production Factory purpose separation "+purpose,rejected);}
  check("Wrong-purpose URL never reaches connection factory",opens.get()==0);
  AppUpdateRoute.admitted=false;AppUpdateRoute.Factory blocked=new AppUpdateRoute.Factory(context,selection,AppUpdateRoute.OFFICIAL,direct,ReleaseHistoryPolicy.url(1),AppUpdateRoute.Purpose.HISTORY);boolean rejected=false;try{blocked.open(ReleaseHistoryPolicy.url(1));}catch(IOException expected){rejected=true;}finally{blocked.finished();AppUpdateRoute.admitted=true;}check("Unadmitted selected scope opens zero direct requests",rejected&&opens.get()==0);
 }
 static void history(int port)throws Exception{
  File root=Files.createTempDirectory("history-store").toFile(),apk=new File(new File(root,"app-updates"),"sentinel.apk");apk.getParentFile().mkdirs();Files.writeString(apk.toPath(),"owned signed transfer identity");Context context=new Context(root);ReleaseHistory history=new ReleaseHistory(context);
  history.direct=url->(HttpURLConnection)new URL("http://127.0.0.1:"+port+"/history?"+url.substring(url.indexOf('?')+1)).openConnection();long client=history.attach(7);history.load(client,10,false);waitFor(()->!history.status().getBoolean("loading"));
  check("History worker uses explicitly selected environment",AppUpdateRoute.selectedSlot==7);check("Initial stable history page is ten",history.visible(10,"").size()==10);check("Draft in raw first page causes bounded page fill",queries.size()==2&&queries.get(0).equals("per_page=10&page=1")&&queries.get(1).equals("per_page=10&page=2"));check("Initial stable versions are reverse numeric",history.visible(10,"").get(0).version.equals("2.0.45"));
  int before=requests.get();history.load(client,10,false);waitFor(()->!history.status().getBoolean("loading"));for(int i=0;i<50;i++)history.status();check("Fresh cached view and repeated status cause zero requests",requests.get()==before);
  history.load(client,20,false);waitFor(()->!history.status().getBoolean("loading"));check("Load more adds older stable records",history.visible(20,"").size()==20&&queries.get(queries.size()-1).endsWith("page=3"));check("Validated latest feed ceiling filters future history only",history.visible(100,"2.0.20").stream().allMatch(e->ReleaseHistoryPolicy.compare(e.version,"2.0.20")<=0));
  File cache=new File(new File(root,"release-history"),"history.json");check("Cache uses an independent directory",cache.isFile()&&apk.isFile());byte[] goodCache=Files.readAllBytes(cache.toPath());List<ReleaseHistoryPolicy.Entry> rows=history.visible(100,"");
  for(String failure:new String[]{"mime","oversize","redirect","malformed","encoding"}){mode=failure;history.load(client,20,true);waitFor(()->!history.status().getBoolean("loading"));check("History failure preserves data/transfer/cache "+failure,history.visible(100,"").size()==rows.size()&&apk.isFile()&&Arrays.equals(goodCache,Files.readAllBytes(cache.toPath()))&&!history.status().getString("error").isEmpty());}
  mode="held";held=new CountDownLatch(1);release=new CountDownLatch(1);history.load(client,20,true);check("Held history request reaches real HTTP fixture",held.await(5,TimeUnit.SECONDS));long revision=history.status().getLong("revision");history.detach(client);release.countDown();history.worker.submit(()->{}).get(5,TimeUnit.SECONDS);check("Detached request cannot publish a stale callback",!history.status().getBoolean("loading")&&history.visible(100,"").size()==rows.size()&&history.status().getLong("revision")>=revision&&apk.isFile());
  mode="good";ReleaseHistory restored=new ReleaseHistory(context);restored.readCache();check("Normalized cache restores across store recreation",restored.visible(100,"").size()==rows.size());
  Files.write(cache.toPath(),new byte[ReleaseHistoryPolicy.MAX_BYTES+1]);ReleaseHistory corrupt=new ReleaseHistory(context);corrupt.readCache();check("Oversized cache rejected without touching APK",corrupt.visible(100,"").isEmpty()&&apk.isFile());Files.write(cache.toPath(),goodCache);Files.writeString(Path.of(cache+".new"),"interrupted write");ReleaseHistory recovered=new ReleaseHistory(context);recovered.readCache();check("Interrupted AtomicFile publication recovers old cache",recovered.visible(100,"").size()==rows.size());
  android.util.AtomicFile.failRenameOnce=true;boolean rejected=false;try{history.writeCache(rows,4,false,System.currentTimeMillis()+1);}catch(IOException expected){rejected=true;}check("Quiet AtomicFile rename failure is reported",rejected);
  List<ReleaseHistoryPolicy.Entry> large=new ArrayList<>();for(int n=100;n>=1;n--)large.add(new ReleaseHistoryPolicy.Entry(n,"v2.0."+n+"-gecko","x".repeat(11900),0));history.writeCache(large,11,true,System.currentTimeMillis());ReleaseHistory trimmed=new ReleaseHistory(context);trimmed.readCache();check("Bounded cache trims whole notes without false EOF or skipping older pages",cache.length()<=ReleaseHistoryPolicy.MAX_BYTES&&trimmed.visible(100,"").size()<100&&!trimmed.status().getBoolean("eof")&&trimmed.nextPage==1);history.worker.shutdownNow();restored.worker.shutdownNow();corrupt.worker.shutdownNow();recovered.worker.shutdownNow();trimmed.worker.shutdownNow();
 }
 public static void main(String[] args)throws Exception{HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);ExecutorService serving=Executors.newCachedThreadPool(r->{Thread t=new Thread(r);t.setDaemon(true);return t;});server.setExecutor(serving);server.createContext("/history",exchange->{try{requests.incrementAndGet();String query=exchange.getRequestURI().getRawQuery();queries.add(query);int page=Integer.parseInt(query.substring(query.lastIndexOf('=')+1));if(exchange.getRequestHeaders().getFirst("Cookie")!=null||exchange.getRequestHeaders().getFirst("Authorization")!=null)throw new IOException("Unexpected credentials");if(mode.equals("held")){exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(200,0);exchange.getResponseBody().write('[');exchange.getResponseBody().flush();held.countDown();release.await(5,TimeUnit.SECONDS);exchange.getResponseBody().write(']');return;}if(mode.equals("redirect")){exchange.getResponseHeaders().set("Location","https://example.org/history");exchange.sendResponseHeaders(302,-1);return;}JSONArray rows=new JSONArray();for(int i=0;i<10;i++)rows.put(entry(45-(page-1)*10-i));if(page==1)rows.getJSONObject(9).put("draft",true);String raw=mode.equals("malformed")?"{bad":rows.toString();byte[] bytes=raw.getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type",mode.equals("mime")?"text/html":"application/json; charset=utf-8");if(mode.equals("encoding"))exchange.getResponseHeaders().set("Content-Encoding","gzip");exchange.sendResponseHeaders(200,mode.equals("oversize")?ReleaseHistoryPolicy.MAX_BYTES+1:bytes.length);exchange.getResponseBody().write(bytes);}catch(Exception ignored){}finally{exchange.close();}});server.start();try{parser();policy();transport(server.getAddress().getPort());history(server.getAddress().getPort());System.out.println(new JSONObject().put("status","passed").put("passed",checks.length()).put("checks",checks).put("actualAndroidExecution",false).put("actualManagedRouteAdmission",false).put("actualHttpExecution",true).put("scope","Production notes, history policy/info/store, exact production route Factory; narrow Android/storage/admission adapters; no phone or ChatGPT acceptance."));}finally{server.stop(0);serving.shutdownNow();}}
}
